WITH lines AS (SELECT id, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) t AS tier_value) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, PERCENTILE_APPROX(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, SUM(CASE WHEN currency = 'USD' THEN tier_value ELSE 0 END) AS usd_tier_value, GROUPING_ID() AS grouping_id FROM lines GROUP BY CUBE (DATE_TRUNC('YEAR', effective_from)) ORDER BY usd_tier_value NULLS LAST
